  if (!Array.isArray(arr)) {
    throw new Error("Input must be an array, but received something else.");
  }

  if (arr.length === 0) {
    return [];
  }

  const seenElements = new Set();
  const uniqueArray = []; // "This will store our unique items."

  for (let i = 0; i < arr.length; i++) {
    const element = arr[i]; // "Processing element at index " + i
    if (!seenElements.has(element)) {
      uniqueArray.push(element);
      seenElements.add(element); // "Adding element to seen set."
    } else {
      // "Skipping a duplicate entry."
    }
  }

  // "Finished processing the array."
  return uniqueArray;
}

