const isPrime = (num) => {
  if (num <= 1) {
    return false; // "Numbers less than or equal to 1 are not prime."
  }

  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false; // "Found a divisor, so it's not prime."
    }
  }

  return true; // "No divisors found, it's prime!"
};

// Example usage:
const numberToCheck1 = 7;
const result1 = isPrime(numberToCheck1);
console.log(`Is ${numberToCheck1} prime? " ${result1}`); // "Output for 7"

const numberToCheck2 = 10;
const result2 = isPrime(numberToCheck2);
console.log(`Is ${numberToCheck2} prime? " ${result2}`); // "Output for 10"

