  if (!realDate) {
    throw new Error('birthdate is not a real calendar date: ' + birthdateStr);
  }
  return { year, month, day };
}

function calculateAge(birthdateStr) {
  const birth = parseBirthdate(birthdateStr);
  const today = new Date();
  const currentYear = today.getFullYear();
  const currentMonth = today.getMonth() + 1;
  const currentDay = today.getDate();

  let age = currentYear - birth.year;
  const beforeBirthday =
    currentMonth < birth.month ||
    (currentMonth === birth.month && currentDay < birth.day);
  if (beforeBirthday) {
    age -= 1;
  }
  if (age < 0) {
    throw new RangeError('birthdate lies in the future: ' + birthdateStr);
  }
  return age;
}

function formatBirthdate(birthdateStr) {
  const birth = parseBirthdate(birthdateStr);
  const monthName = MONTH_NAMES[birth.month - 1];
  const dayAndYear = [birth.day, birth.year].join(', ');
  return [monthName, dayAndYear].join(' ');
}

function describeAge(birthdateStr) {
  const age = calculateAge(birthdateStr);
  let unit = 'years old';
  if (age === 1) {
    unit = 'year old';
  }
  const phrase = [age, unit].join(' ');
  return [formatBirthdate(birthdateStr), phrase].join(': ');
}

function main() {
  const samples = [
    '1990-01-01',
    '2020-10-27',
    '1968-02-29',
    '1990-13-01',
    'not-a-date',
    '2100-06-15'
  ];
  for (const sample of samples) {
    try {
      console.log(describeAge(sample));
    } catch (err) {
      console.log([sample, err.message].join(' rejected: '));
    }
  }
}

main();

module.exports = { calculateAge, parseBirthdate, formatBirthdate, describeAge };

