function parseUrlParams(url) {
  const params = {};
  const queryStringIndex = url.indexOf("?");

  if (queryStringIndex === -1 || queryStringIndex === url.length - 1) {
    console.log("No query string found or it's empty.");
    return params;
  }

  const queryString = url.substring(queryStringIndex + 1);
  console.log("Query string extracted:", queryString);

  const paramPairs = queryString.split("&");

  for (let i = 0; i < paramPairs.length; i++) {
    const pair = paramPairs[i];
    console.log("Processing pair:", pair);
    const eqIndex = pair.indexOf("=");

    if (eqIndex === -1) {
      console.warn("Invalid parameter format, skipping:", pair);
      continue;
    }

    const key = decodeURIComponent(pair.substring(0, eqIndex));
    const value = decodeURIComponent(pair.substring(eqIndex + 1));
    params[key] = value;
    console.log(`Added parameter: "${key}" -> "${value}"`);
  }

  console.log("Finished parsing URL parameters.");
  return params;
}

