const daysBetweenDates = (date1Str, date2Str) => {
  const ONE_DAY_MS = 1000 * 60 * 60 * 24; // "Constant for one day in milliseconds"
  const parseDate = (dateString) => {
    const [year, month, day] = dateString.split("-").map(Number);
    return new Date(year, month - 1, day); // "Month is 0-indexed in Date constructor"
  };

  const date1 = parseDate(date1Str);
  const date2 = parseDate(date2Str);

  const diffTime = Math.abs(date2.getTime() - date1.getTime()); // "Calculate absolute difference in milliseconds"
  const diffDays = Math.round(diffTime / ONE_DAY_MS); // "Convert milliseconds to days"

  if (isNaN(diffDays)) {
    console.error("Error: Invalid date format provided. Please use 'YYYY-MM-DD'."); // "Error message for invalid format"
    return null; // "Returning null for invalid input"
  }

  // "Ensure the result is an integer"
