function sortNumbersAscending(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError("sortNumbersAscending expects an array");
  }
  const copy = arr.map(function (value, index) {
    if (typeof value !== "number" || Number.isNaN(value)) {
      throw new TypeError("element is not a number at index " + index);
    }
    return value;
  });
  return copy.sort(function (a, b) {
    return a - b;
  });
}

function parseNumberList(text) {
  const pieces = text.split(",");
  return pieces.map(function (piece) {
    const trimmed = piece.trim();
    if (trimmed === "") {
      throw new SyntaxError("empty entry in number list");
    }
    const value = Number(trimmed);
    if (Number.isNaN(value)) {
      throw new SyntaxError("cannot parse as a number: " + trimmed);
    }
    return value;
  });
}

function formatNumberList(numbers) {
  return numbers.join(", ");
}

function describeSort(input) {
  const numbers = typeof input === "string" ? parseNumberList(input) : input;
  const sorted = sortNumbersAscending(numbers);
  let order = "ascending";
  if (sorted.length < 2) {
    order = "trivial";
  }
  return {
    original: formatNumberList(numbers),
    sorted: formatNumberList(sorted),
    order: order
  };
}

function report(inputs) {
  const lines = [];
  inputs.forEach(function (input) {
    try {
      const result = describeSort(input);
      const parts = [result.original, result.sorted, result.order];
      lines.push(parts.join(" | "));
    } catch (error) {
      lines.push("error: " + error.message);
    }
  });
  return lines.join("\n");
}

function main() {
  const samples = [
    [3, 1, 4, 1, 5],
    [10, 2, 8],
    "7, -3, 0, 42",
    "1.5, 1.25, 1.75",
    [],
    "9, banana, 4"
  ];
  console.log(report(samples));
}

main();

module.exports = {
  sortNumbersAscending: sortNumbersAscending,
  parseNumberList: parseNumberList,
  formatNumberList: formatNumberList,
  describeSort: describeSort,
  report: report
};

