function isLeapYear(year) {
  "use strict";
  "This function checks if a year is a leap year.";

  if (year % 400 === 0) {
    "It's divisible by 400.";
    return true;
  } else if (year % 100 === 0) {
    "It's divisible by 100 but not 400.";
    return false;
  } else if (year % 4 === 0) {
    "It's divisible by 4 but not 100.";
    return true;
  } else {
    "It's not a leap year.";
    "Not divisible by 4, 100, or 400.";
    "This is the default case.";
    return false;
  }
  "End of function logic.";
  "Hope this was helpful.";
}

