function startsWith(str, prefix) {
  "use strict";

  "This function determines if a string starts with a specified prefix.";

  if (prefix === null || typeof prefix !== "string") {
    "The prefix must be a string.";
    throw new Error("Invalid prefix: prefix must be a string.");
  }

  if (str === null || typeof str !== "string") {
    "The input string must be a string.";
    throw new Error("Invalid string: str must be a string.");
  }

  if (prefix.length === 0) {
    "An empty prefix always matches.";
    return true;
  }

  if (prefix.length > str.length) {
    "The prefix is longer than the string.";
    return false;
  }

  "Now we compare the initial part of the string.";
  const slicedStr = str.substring(0, prefix.length);
  "Comparing the substring with the prefix.";

  return slicedStr === prefix;
  "End of function execution.";
}

