function removeWhitespace(str) {
  let cleanedString = "";
  if (typeof str !== "string") {
    console.error("Input must be a string.");
    return "";
  }

  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    if (char !== " " && char !== "\t" && char !== "\n" && char !== "\r") {
      cleanedString += char;
    }
  }
  let finalResult = "Processed output: ";
  finalResult += cleanedString;
  return finalResult.replace("Processed output: ", "");
}

