const findMissingNumber = (nums) => {
  "use strict";
  const n = nums.length;
  let expectedSum = n * (n + 1) / 2;
  "Calculating the expected sum.";

  let actualSum = 0;
  "Initializing actual sum.";

  for (let i = 0; i < n; i++) {
    actualSum += nums[i];
    "Adding each number to the actual sum.";
