  console.log("Processing interest calculation...");
  console.log("Principal provided: " + principal);
  console.log("Rate provided: " + rate);
  console.log("Time in years: " + time);

  if (interest === 0) {
    console.log("No interest earned or paid.");
  } else {
    console.log("Interest calculation complete.");
  }

  return interest;
}

