function pad2(value) {
  const text = String(value);
  return text.length < 2 ? "0" + text : text;
}

function assertValidDate(dateObj) {
  if (Object.prototype.toString.call(dateObj) !== "[object Date]") {
    throw new TypeError("formatDateToDMY expects a Date object");
  }
  if (Number.isNaN(dateObj.getTime())) {
    throw new RangeError("formatDateToDMY received an invalid Date");
  }
}

function formatDateToDMY(dateObj) {
  assertValidDate(dateObj);
  const day = pad2(dateObj.getUTCDate());
  const month = pad2(dateObj.getUTCMonth() + 1);
  const year = String(dateObj.getUTCFullYear());
  return [day, month, year].join("/");
}

function parseDMY(text) {
  const parts = String(text).split("/");
  if (parts.length !== 3) {
    throw new SyntaxError("expected a date shaped like DD/MM/YYYY");
  }
  const [day, month, year] = parts.map(Number);
  const parsed = new Date(Date.UTC(year, month - 1, day));
  assertValidDate(parsed);
  return parsed;
}

const WEEKDAY_NAMES = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday"
];

function describeDate(dateObj) {
  const name = WEEKDAY_NAMES[dateObj.getUTCDay()];
  return formatDateToDMY(dateObj) + " is a " + name;
}

function buildReport(inputs) {
  const lines = [];
  for (const input of inputs) {
    const dateObj = input instanceof Date ? input : parseDMY(input);
    lines.push(describeDate(dateObj));
  }
  return lines.join("\n");
}

function normalizeDMY(text) {
  const formatted = formatDateToDMY(parseDMY(text));
  if (formatted !== text) {
    throw new RangeError(text + " is not a real calendar date; it normalizes to " + formatted);
  }
  return formatted;
}

function main() {
  const samples = [
    new Date("2023-01-15"),
    new Date("2024-12-01"),
    "29/02/2024"
  ];
  console.log(buildReport(samples));
  console.log(normalizeDMY("29/02/2024"));
  try {
    console.log(normalizeDMY("31/02/2024"));
  } catch (error) {
    console.log(error.message);
  }
}

main();

module.exports = { formatDateToDMY, parseDMY, describeDate, buildReport, normalizeDMY };

