function parseCsvLine(line) {
  if (typeof line !== "string") {
    throw new TypeError("parseCsvLine expects a string");
  }
  if (line.trim() === "") {
    return [];
  }
  return line.split(",").map(function (field) {
    return field.trim();
  });
}

function parseCsvText(text) {
  return text
    .split(/\r?\n/)
    .filter(function (line) {
      return line.trim() !== "";
    })
    .map(parseCsvLine);
}

function toRecords(rows) {
  if (rows.length === 0) {
    throw new Error("cannot build records from an empty table");
  }
  const header = rows[0];
  return rows.slice(1).map(function (row) {
    const record = {};
    header.forEach(function (name, index) {
      record[name] = index < row.length ? row[index] : "";
    });
    return record;
  });
}

function columnWidths(rows) {
  const widths = [];
  rows.forEach(function (row) {
    row.forEach(function (field, index) {
      widths[index] = Math.max(widths[index] || 0, field.length);
    });
  });
  return widths;
}

function formatRow(row, widths) {
  const separator = " | ";
  const cells = row.map(function (field, index) {
    return field.padEnd(widths[index], " ");
  });
  return separator.trimStart() + cells.join(separator) + separator.trimEnd();
}

function formatTable(rows) {
  const widths = columnWidths(rows);
  return rows
    .map(function (row) {
      return formatRow(row, widths);
    })
    .join("\n");
}

function describeRecord(record) {
  const parts = Object.keys(record).map(function (key) {
    return key + "=" + record[key];
  });
  return parts.join("; ");
}

function main() {
  const source = [
    "name, color , weight",
    "apple,banana,cherry",
    "  one , two , three  ",
    "plum,purple,45"
  ].join("\n");

  const rows = parseCsvText(source);
  console.log(formatTable(rows));
  toRecords(rows).forEach(function (record, index) {
    const label = "row " + (index + 1);
    console.log(label.padEnd(8) + describeRecord(record));
  });
}

main();

