function validateRect(rect, label) {
  if (!Array.isArray(rect)) {
    throw new TypeError(label + " must be an array of four numbers");
  }
  if (rect.length !== 4) {
    throw new TypeError(label + " must contain exactly four coordinates");
  }
  rect.forEach(function (value, index) {
    if (typeof value !== "number" || !Number.isFinite(value)) {
      const where = label + " coordinate " + index;
      throw new TypeError(where + " is not a finite number");
    }
  });
  return rect;
}

function normalizeRect(rect) {
  const [x1, y1, x2, y2] = rect;
  return {
    left: Math.min(x1, x2),
    right: Math.max(x1, x2),
    bottom: Math.min(y1, y2),
    top: Math.max(y1, y2)
  };
}

function doRectanglesOverlap(rect1, rect2) {
  const a = normalizeRect(validateRect(rect1, "rect1"));
  const b = normalizeRect(validateRect(rect2, "rect2"));
  return a.left < b.right && b.left < a.right && a.bottom < b.top && b.bottom < a.top;
}

function overlapArea(rect1, rect2) {
  if (!doRectanglesOverlap(rect1, rect2)) {
    return 0;
  }
  const a = normalizeRect(rect1);
  const b = normalizeRect(rect2);
  const width = Math.min(a.right, b.right) - Math.max(a.left, b.left);
  const height = Math.min(a.top, b.top) - Math.max(a.bottom, b.bottom);
  return width * height;
}

function formatRect(rect) {
  let text = "[";
  text += rect.join(", ");
  return text + "]";
}

function describePair(rect1, rect2) {
  const overlapping = doRectanglesOverlap(rect1, rect2);
  let verb = "do not overlap";
  if (overlapping) {
    verb = "overlap";
  }
  const pair = formatRect(rect1) + " and ";
  let line = pair + formatRect(rect2) + " ";
  line += verb;
  if (overlapping) {
    line += ", shared area ";
    line += overlapArea(rect1, rect2);
  }
  return line;
}

function main() {
  const pairs = [
    [[0, 0, 2, 2], [1, 1, 3, 3]],
    [[0, 0, 1, 1], [2, 2, 3, 3]],
    [[-4, 6, 0, 2], [-2, 4, 5, -1]]
  ];
  console.log("Rectangle overlap report");
  pairs.forEach(function (pair) {
    const indent = "  ";
    console.log(indent + describePair(pair[0], pair[1]));
  });
  try {
    doRectanglesOverlap([0, 0, 2], [1, 1, 3, 3]);
  } catch (error) {
    console.log("Rejected input: " + error.message);
  }
}

main();

module.exports = { doRectanglesOverlap, overlapArea, describePair };

