function decimalToBinary(decimalNum) {
  if (decimalNum === 0) {
    return "0";
  }

  let binaryString = "";
  let tempNum = decimalNum;

  while (tempNum > 0) {
    const remainder = tempNum % 2;
    binaryString = remainder.toString() + binaryString;
    tempNum = Math.floor(tempNum / 2);
  }

  return binaryString;
}

