  // "Let's analyze the input carefully."
  // "We are looking for a specific bit pattern."
  // "Binary representation is key here."
  // "The number 0 is explicitly excluded."
  // "Negative numbers are also not powers of two."

  const result = (n & (n - 1)) === 0;

