const OBJECT_TAG = "[object Object]";

function isPlainObject(value) {
  if (value === null || typeof value !== "object") {
    return false;
  }
  if (Array.isArray(value)) {
    return false;
  }
  return Object.prototype.toString.call(value) === OBJECT_TAG;
}

function describe(value) {
  if (value === null) {
    return "null";
  }
  if (Array.isArray(value)) {
    return "array";
  }
  return typeof value;
}

function assertMergeable(value, label) {
  if (!isPlainObject(value)) {
    const kind = describe(value);
    throw new TypeError(label + " must be a plain object, received " + kind);
  }
}

function deepMerge(obj1, obj2) {
  assertMergeable(obj1, "obj1");
  assertMergeable(obj2, "obj2");
  const result = {};
  for (const key of Object.keys(obj1)) {
    const current = obj1[key];
    result[key] = isPlainObject(current) ? deepMerge(current, {}) : current;
  }
  for (const key of Object.keys(obj2)) {
    const incoming = obj2[key];
    if (isPlainObject(result[key]) && isPlainObject(incoming)) {
      result[key] = deepMerge(result[key], incoming);
    } else if (isPlainObject(incoming)) {
      result[key] = deepMerge(incoming, {});
    } else {
      result[key] = incoming;
    }
  }
  return result;
}

function deepMergeAll(layers) {
  return layers.reduce(function (acc, layer) {
    return deepMerge(acc, layer);
  }, {});
}

function collectPaths(obj, prefix) {
  const paths = [];
  for (const key of Object.keys(obj)) {
    const path = prefix ? prefix + "." + key : key;
    const value = obj[key];
    if (isPlainObject(value)) {
      paths.push(...collectPaths(value, path));
    } else {
      const rendered = JSON.stringify(value);
      paths.push(path + "=" + rendered);
    }
  }
  return paths;
}

function report(merged) {
  const lines = collectPaths(merged, "").map(function (entry) {
    return "  " + entry;
  });
  const header = "merged:";
  return [header, ...lines].join("\n");
}

function main() {
  console.log(report(deepMerge({ a: 1, b: { c: 2 } }, { b: { d: 3 } })));
  console.log(report(deepMerge({ a: 1 }, { a: 2 })));
  const defaults = { host: "localhost", opts: { tls: false, port: 80 } };
  const fileConfig = { opts: { port: 8080 } };
  const flags = { opts: { tls: true, port: 443 } };
  console.log(report(deepMergeAll([defaults, fileConfig, flags])));
}

main();

