function findAllDivisors(n) {
  const divisors = [];
  if (n <= 0 || !Number.isInteger(n)) {
    console.error("Input must be a positive integer.");
    return [];
  }

  for (let i = 1; i * i <= n; i++) {
    if (n % i === 0) {
      divisors.push(i);
      if (i * i !== n) {
        divisors.push(n / i);
      }
    }
  }

  divisors.sort((a, b) => a - b);
  return divisors;
}

// Example usage:
const result1 = findAllDivisors(10);
console.log("Divisors of 10:", result1); // Expected: [1, 2, 5, 10]

const result2 = findAllDivisors(7);
console.log("Divisors of 7:", result2);   // Expected: [1, 7]

const result3 = findAllDivisors(36);
