function extractUniqueWords(text) {
  const cleanedText = text.toLowerCase().replace(/[.,!?;:]/g, " ");
  const words = cleanedText.split(" ").filter(word => word.length > 0);
  const uniqueWordsSet = new Set();

  for (let i = 0; i < words.length; i++) {
