function assertNumericArray(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError("calculateStandardDeviation expects an array of numbers");
  }
  numbers.forEach(function (value, index) {
    if (typeof value !== "number" || !Number.isFinite(value)) {
      const location = "entry #" + index;
      throw new TypeError(location + " is not a finite number");
    }
  });
}

function calculateMean(numbers) {
  const total = numbers.reduce(function (sum, value) {
    return sum + value;
  }, 0);
  return total / numbers.length;
}

function calculateStandardDeviation(numbers) {
  assertNumericArray(numbers);
  if (numbers.length < 2) {
    return 0;
  }
  const mean = calculateMean(numbers);
  const squaredDeviations = numbers.reduce(function (sum, value) {
    const deviation = value - mean;
    return sum + deviation * deviation;
  }, 0);
  return Math.sqrt(squaredDeviations / (numbers.length - 1));
}

function parseSeries(text) {
  return text.split(",").map(function (piece) {
    const trimmed = piece.trim();
    if (trimmed === "") {
      const reason = "empty field in series: ";
      throw new SyntaxError(reason + text);
    }
    const value = Number(trimmed);
    if (Number.isNaN(value)) {
      throw new SyntaxError("not a number: " + trimmed);
    }
    return value;
  });
}

function formatReport(label, numbers) {
  const columns = [label];
  columns.push("n=" + numbers.length);
  columns.push("mean=" + calculateMean(numbers).toFixed(3));
  columns.push("sd=" + calculateStandardDeviation(numbers).toFixed(3));
  return columns.join(" | ");
}

function main() {
  const labels = [
    "one through five",
    "constant tens",
    "temperatures"
  ];
  const samples = [
    "1, 2, 3, 4, 5",
    "10, 10, 10",
    "18.5, 20.1, 19.7, 22.3, 21.0, 17.8"
  ];
  labels.forEach(function (label, index) {
    const numbers = parseSeries(samples[index]);
    console.log(formatReport(label, numbers));
  });
}

main();

