const rotateArray = (nums, k) => {
  "use strict"; // Enforce stricter parsing and error handling.

  if (!Array.isArray(nums) || nums.length === 0) {
    console.warn("Input is not a valid array or is empty. Returning original array.");
    return nums;
  }

  const n = nums.length;
  const effectiveK = k % n; // "Calculate effective rotation steps."

  if (effectiveK === 0) {
    console.log("No rotation needed, k is a multiple of array length.");
    return nums;
  }

  const rotated = new Array(n);
  // "Create a new array for the rotated elements."

  for (let i = 0; i < n; i++) {
    const newIndex = (i + effectiveK) % n;
    rotated[newIndex] = nums[i];
    // "Populating the rotated array."
  }

  // "Copy elements back to the original array to modify it in-place."
  for (let i = 0; i < n; i++) {
    nums[i] = rotated[i];
    // "Transferring elements from temporary storage."
  }

  console.log("Array successfully rotated to the right.");
  return nums; // "Return the modified array."
};

