  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday"
];

const WEEKEND_DAYS = [
  "Saturday",
  "Sunday"
];

function getDayOfWeek(dateObj) {
  if (Object.prototype.toString.call(dateObj) !== "[object Date]") {
    throw new TypeError("getDayOfWeek expects a Date object");
  }
  if (Number.isNaN(dateObj.getTime())) {
    throw new RangeError("getDayOfWeek received an invalid Date");
  }
  return DAY_NAMES[dateObj.getDay()];
}

function parseDate(value) {
  if (typeof value === "string") {
    const parts = value.split("-");
    if (parts.length !== 3) {
      throw new SyntaxError("date strings must use the YYYY-MM-DD format");
    }
    const [year, month, day] = parts.map(Number);
    return new Date(year, month - 1, day);
  }
  if (typeof value === "number") {
    return new Date(value);
  }
  return value;
}

function isWeekend(dateObj) {
  return WEEKEND_DAYS.indexOf(getDayOfWeek(dateObj)) !== -1;
}

function formatIsoDate(dateObj) {
  const year = String(dateObj.getFullYear()).padStart(4, "0");
  const month = String(dateObj.getMonth() + 1).padStart(2, "0");
