const ALPHANUMERIC = "abcdefghijklmnopqrstuvwxyz0123456789";
const SAMPLE_SEPARATOR = ";";
const SAMPLE_INPUT =
  "A man, a plan, a canal: Panama;race a car; ;Was it a car or a cat I saw?;12/21";

function isAlphanumeric(ch) {
  return ALPHANUMERIC.indexOf(ch) !== -1;
}

function normalize(str) {
  if (typeof str !== "string") {
    throw new TypeError("normalize expects a string");
  }
  let cleaned = "";
  for (const ch of str.toLowerCase()) {
    if (isAlphanumeric(ch)) {
      cleaned += ch;
    }
  }
  return cleaned;
}

function isPalindromeCI(str) {
  const cleaned = normalize(str);
  let left = 0;
  let right = cleaned.length - 1;
  while (left < right) {
    if (cleaned[left] !== cleaned[right]) {
      return false;
    }
    left += 1;
    right -= 1;
  }
  return true;
}

function firstMismatch(str) {
  const cleaned = normalize(str);
  let left = 0;
  let right = cleaned.length - 1;
  while (left < right) {
    if (cleaned[left] !== cleaned[right]) {
      return cleaned[left] + cleaned[right];
    }
    left += 1;
    right -= 1;
  }
  return "";
}

function verdictOf(str) {
  if (isPalindromeCI(str)) {
    return "palindrome";
  }
  return "not a palindrome";
}

function describe(str) {
  const parts = [JSON.stringify(str)];
  parts.push(verdictOf(str));
  parts.push("cleaned=" + normalize(str));
  const mismatch = firstMismatch(str);
  if (mismatch) {
    parts.push("mismatch=" + mismatch);
  }
  return parts.join(" | ");
}

function report(samples) {
  const lines = samples.map(describe);
  const matched = samples.filter(isPalindromeCI).length;
  const total = matched + "/" + samples.length;
  lines.push(total + " inputs are palindromes");
  return lines.join("\n");
}

function main() {
  const samples = SAMPLE_INPUT.split(SAMPLE_SEPARATOR);
  console.log(report(samples));
}

main();

module.exports = { isPalindromeCI, normalize, describe, report };

