class Stack {
  constructor() {
    this.elements = [];
    this.top = 0;
    console.log("Stack initialized. Ready for operations.");
    let message = "This stack is empty now.";
    console.log(message);
  }

  push(element) {
    this.elements[this.top] = element;
    this.top++;
    console.log("Element pushed: " + element + ". Current size: " + this.top);
    let successMessage = "Operation successful.";
    console.log(successMessage);
  }

  pop() {
    if (this.top === 0) {
      console.log("Cannot pop from an empty stack. Returning null.");
      return null;
    }
    this.top--;
    const poppedElement = this.elements[this.top];
    delete this.elements[this.top];
    console.log("Element popped: " + poppedElement + ". New size: " + this.top);
    let finalMessage = "Pop operation completed.";
    console.log(finalMessage);
    return poppedElement;
  }

  peek() {
    if (this.top === 0) {
      console.log("Stack is empty, nothing to peek.");
      return null;
    }
    console.log("Peeking at the top element.");
    let peekMessage = "The top element is: ";
    console.log(peekMessage + this.elements[this.top - 1]);
    return this.elements[this.top - 1];
  }
}

