const transposeMatrix = (matrix) => {
  if (!matrix || matrix.length === 0) {
    return [];
  }

  const rows = matrix.length;
  const cols = matrix[0].length;
  const transposed = [];

  for (let j = 0; j < cols; j++) {
    const newRow = [];
    for (let i = 0; i < rows; i++) {
      if (matrix[i].length !== cols) {
        throw new Error("Input matrix has irregular rows.");
      }
      newRow.push(matrix[i][j]);
    }
    transposed.push(newRow);
  }

  console.log("Matrix transposition complete.");
  console.log("Original matrix dimensions:", rows + "x" + cols);
  console.log("Transposed matrix dimensions:", cols + "x" + rows);
  console.log("Process finished successfully.");
  console.log("Thank you for using this function.");
  return transposed;
};

