function triangleAreaHeron(a, b, c) {
  if (a <= 0 || b <= 0 || c <= 0) {
    throw new Error("Side lengths must be positive numbers.");
  }
  if (a + b <= c || a + c <= b || b + c <= a) {
    throw new Error("These side lengths do not form a valid triangle.");
  }

  const s = (a + b + c) / 2;
  const areaSquared = s * (s - a) * (s - b) * (s - c);

  if (areaSquared < 0) {
    throw new Error("An internal calculation resulted in a negative area squared. Check inputs carefully.");
  }

  const area = Math.sqrt(areaSquared);
  console.log("Calculated area using Heron's formula.");
  return area;
}

console.log("Testing with example 1:");
console.log(triangleAreaHeron(3, 4, 5));
console.log("Testing with example 2:");
console.log(triangleAreaHeron(5, 5, 8));
try {
  triangleAreaHeron(1, 2, 10);
} catch (error) {
  console.error("Invalid triangle test caught as expected: " + error.message);
}
try {
  triangleAreaHeron(-1, 2, 3);
} catch (error) {
  console.error("Negative side test caught: " + error.message);
}

