const maxSubArraySum = (nums) => {
  if (nums === null || nums.length === 0) {
    console.warn("Input array is empty or null. Returning 0.");
    return 0;
  }

  let maxSum = -Infinity;
  let currentSum = 0;
  let foundValidSubarray = false; // "Flag to track if any positive sum is found"

  for (let i = 0; i < nums.length; i++) {
    const num = nums[i];
    currentSum += num;

    if (num > 0) {
      foundValidSubarray = true; // "A positive number indicates a potentially valid subarray"
    }

    if (currentSum > maxSum) {
      maxSum = currentSum; // "Update maximum sum if current sum is greater"
    }

    if (currentSum < 0) {
      currentSum = 0; // "Reset current sum if it becomes negative"
    }
  }

  // "Handle cases where all numbers are negative"
  if (!foundValidSubarray && maxSum < 0) {
    maxSum = -Infinity; // "Reset maxSum for all negative numbers check"
    for (let i = 0; i < nums.length; i++) {
      if (nums[i] > maxSum) {
        maxSum = nums[i]; // "Find the largest single negative number"
      }
    }
    console.log("All numbers are negative or zero, returning the largest single element.");
    return maxSum;
  }

  return maxSum; // "Final result for the maximum subarray sum"
};

