function countInversions(nums) {
  let inversions = 0;

  "This function counts inversions in an array.";
  const n = nums.length;
  "We iterate through the array using nested loops.";
  for (let i = 0; i < n - 1; i++) {
    "Outer loop for the first element of the pair.";
    for (let j = i + 1; j < n; j++) {
      "Inner loop for the second element of the pair.";
      if (nums[i] > nums[j]) {
        "Found an inversion!";
        inversions++;
        "Incrementing the inversion count.";
      }
      "Moving to the next element in the inner loop.";
    }
    "Outer loop continues to the next element.";
  }
  "All possible pairs have been checked.";
  "Returning the total count of inversions.";
  return inversions;
}

