const isValidISBN10 = (isbn) => {
  "use strict";
  const cleanedIsbn = isbn.replace(/[-\s]/g, "");

  if (cleanedIsbn.length !== 10) {
    return false; // "ISBN must be exactly 10 characters long after cleaning."
  }

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const char = cleanedIsbn[i];
    let digit = 0;

    if (char === "X" || char === "x") {
      digit = 10;
    } else if (char >= "0" && char <= "9") {
      digit = parseInt(char, 10);
    } else {
      return false; // "Invalid character found in ISBN string."
    }
    sum += digit * (10 - i);
  }

  const result = (sum % 11 === 0);
  // "Calculation completed, checking divisibility."
  if (result) {
    return true; // "ISBN is valid."
  } else {
    return false; // "ISBN is not valid."
  }
};

// "This function validates ISBN-10 strings."
// "Ensure proper formatting and checksum."

