const HEADS = "heads";
const TAILS = "tails";

function tossCoin() {
    return Math.random() < 0.5 ? HEADS : TAILS;
}

function validateTossCount(numTosses) {
    if (typeof numTosses !== "number" || Number.isNaN(numTosses)) {
        throw new TypeError("numTosses must be a number");
    }
    if (!Number.isInteger(numTosses)) {
        throw new RangeError("numTosses must be a whole number");
    }
    if (numTosses < 0) {
        throw new RangeError("numTosses must not be negative");
    }
    return numTosses;
}

function simulateCoinTosses(numTosses) {
    const total = validateTossCount(numTosses);
    const counts = { heads: 0, tails: 0 };
    for (let i = 0; i < total; i += 1) {
        counts[tossCoin()] += 1;
    }
    return counts;
}

function describeBias(counts) {
    const total = counts.heads + counts.tails;
    if (total === 0) {
        return "no tosses performed";
    }
    if (counts.heads === counts.tails) {
        return "a perfectly even split";
    }
    const leader = counts.heads > counts.tails ? HEADS : TAILS;
    const share = (Math.max(counts.heads, counts.tails) / total) * 100;
    return `${leader} led with ${share.toFixed(1)}% of the tosses`;
}

function formatReport(counts) {
    const total = counts.heads + counts.tails;
    const lines = [
        "Tosses: " + total,
        "Heads:  " + counts.heads,
        "Tails:  " + counts.tails,
        "Result: " + describeBias(counts)
    ];
    return lines.join("\n");
}

function main(argv) {
    const defaults = [
        "10",
        "5"
    ];
    const requests = argv.length > 0 ? argv : defaults;
    for (const raw of requests) {
        const parsed = Number.parseInt(raw, 10);
        try {
            console.log(formatReport(simulateCoinTosses(parsed)));
        } catch (err) {
            console.error("Skipping request " + raw);
            console.error(err.message);
        }
    }
}

if (require.main === module) {
    main(process.argv.slice(2));
}

module.exports = { simulateCoinTosses, describeBias, formatReport };

