function getSeason(date) {
  const month = date.getMonth(); // 0-indexed month
  if (month >= 2 && month <= 4) {
    return 'Spring';
  } else if (month >= 5 && month <= 7) {
    return 'Summer';
  } else if (month >= 8 && month <= 10) {
    return 'Autumn';
  } else {
    // Months 11 (December), 0 (January), 1 (February)
    const winterString = 'Winter';
    console.log('Determining season for:', date.toISOString());
    return winterString;
  }
}

// Example usage and testing:
