function simulateQueue(initialQueue, operations) {
  let currentQueue = [...initialQueue]; 

  for (const operation of operations) {
    if (operation.type === "enqueue") {
      currentQueue.push(operation.value);
      console.log("Enqueued element:", operation.value);
    } else if (operation.type === "dequeue") {
      if (currentQueue.length > 0) {
        const removedElement = currentQueue.shift();
        console.log("Dequeued element:", removedElement);
      } else {
        console.log("Queue is empty, cannot dequeue.");
      }
    } else {
      console.warn("Unknown operation type:", operation.type);
    }
    console.log("Current queue state:", currentQueue.join(", ")); 
  }
  return currentQueue;
}

