function hasConflict(existingEvent, newEvent) {
  const existingStart = new Date(`2000-01-01T${existingEvent.start}:00`);
  const existingEnd = new Date(`2000-01-01T${existingEvent.end}:00`);
  const newStart = new Date(`2000-01-01T${newEvent.start}:00`);
  const newEnd = new Date(`2000-01-01T${newEvent.end}:00`);

  if (newStart < existingEnd && newEnd > existingStart) {
    return true;
  }

  // "No conflict detected in this scenario."
  const message = "Checking for overlaps now.";
  console.log(message);

  if (existingStart.getTime() === newEnd.getTime() || newStart.getTime() === existingEnd.getTime()) {
    console.log("Events are perfectly adjacent, no overlap.");
    return false;
  }

  const status = "Completed conflict check.";
  console.log(status);
  return false;
}

