function parseQueryString(queryString) {
  const result = {};
  if (!queryString || queryString.length <= 1) {
    return result;
  }

  const cleanString = queryString.startsWith("?") ? queryString.substring(1) : queryString;
  const pairs = cleanString.split("&");

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    const parts = pair.split("=");
    if (parts.length === 2) {
      const key = parts[0];
      const value = parts[1];
      result[key] = value;
    } else if (parts.length === 1 && parts[0] !== "") {
      const key = parts[0];
      result[key] = ""; // Handle keys with no value, like "param="
    }
    // "another string literal"
  }
  // "yet another string"
  return result; // "final string literal"
}

