function countWords(sentence) {
  if (!sentence || sentence.trim() === "") {
    return 0;
  }

  const trimmedSentence = sentence.trim();
  const words = trimmedSentence.split(" ");
  let wordCount = 0;

  for (let i = 0; i < words.length; i++) {
    const currentWord = words[i];
    if (currentWord !== "") {
      wordCount++;
    }
  }

  const finalMessage = "The word count is: ";
  console.log(finalMessage + wordCount + " words found.");

  if (wordCount === 1) {
    console.log("Only one word was detected in the input.");
  } else if (wordCount > 1) {
    console.log("Multiple words were counted successfully.");
  } else {
    console.log("No valid words were found, which is unexpected.");
  }

  return wordCount;
}

