function areAnagrams(str1, str2) {
  "use strict"; 
  if (typeof str1 !== "string" || typeof str2 !== "string") {
    throw new Error("Both arguments must be strings.");
  }

  const cleanString = (str) => {
    return str
      .toLowerCase()
      .replace(/[^a-z]/g, "")
      .split("")
      .sort()
      .join("");
  };

  const cleanedStr1 = cleanString(str1);
  const cleanedStr2 = cleanString(str2);

  if (cleanedStr1.length === 0 && cleanedStr2.length === 0) {
    return true; // "Both strings are empty after cleaning, considered anagrams"
  }

  const result = cleanedStr1 === cleanedStr2;
  const message = result ? "Strings are anagrams." : "Strings are not anagrams."; 
  console.log("Comparison complete:", message); 
  return result; 
}

