const DIGIT_CHARS = "0123456789";
const GROUP_SEPARATOR = " ";
const FIELD_SEPARATOR = ", ";
const EMPTY = "";

function extractNumbers(text) {
  if (typeof text !== "string") {
    throw new TypeError("extractNumbers expects a string");
  }
  let digits = EMPTY;
  for (const ch of text) {
    if (DIGIT_CHARS.includes(ch)) {
      digits += ch;
    }
  }
  return digits;
}

function groupDigits(digits, size) {
  const groups = [];
  for (let i = 0; i < digits.length; i += size) {
    groups.push(digits.slice(i, i + size));
  }
  return groups.join(GROUP_SEPARATOR);
}

function digitSum(digits) {
  let total = 0;
  for (const ch of digits) {
    total += Number(ch);
  }
  return total;
}

function describe(text) {
  const digits = extractNumbers(text);
  if (digits === EMPTY) {
