const DIGIT_CHARS = '0123456789';
const GROUP_SEPARATOR = ' ';
const FIELD_SEPARATOR = ', ';
const EMPTY = '';

function extractNumbers(text) {
  if (typeof text !== 'string') {
    throw new TypeError('extractNumbers expects a string');
  }
  let digits = EMPTY;
  for (const ch of text) {
    if (DIGIT_CHARS.includes(ch)) {
      digits += ch;
    }
  }
  return digits;
}

function groupDigits(digits, size) {
  const groups = [];
  for (let i = 0; i < digits.length; i += size) {
    groups.push(digits.slice(i, i + size));
  }
  return groups.join(GROUP_SEPARATOR);
}

function digitSum(digits) {
  let total = 0;
  for (const ch of digits) {
    total += Number(ch);
  }
  return total;
}

function describe(text) {
  const digits = extractNumbers(text);
  if (digits === EMPTY) {
    return 'no digits found';
  }
  const parts = [
    'digits=' + digits,
    'count=' + digits.length,
    'sum=' + digitSum(digits),
    'grouped=' + groupDigits(digits, 3)
  ];
  return parts.join(FIELD_SEPARATOR);
}

function report(samples) {
  const quote = '"';
  const arrow = ' -> ';
  const lines = [];
  for (const sample of samples) {
    const label = quote + sample + quote;
    lines.push(label.padEnd(30) + arrow + describe(sample));
  }
  return lines.join('\n');
}

function main() {
  const samples = [
    'abc123def45',
    'no numbers here',
    'phone: +1 (555) 010-2938',
    'order #7 shipped 2024-06-30'
  ];
