const BEATS = {
  rock: "scissors",
  paper: "rock",
  scissors: "paper"
};

const OUTCOME_P1 = "Player 1 Wins";
const OUTCOME_P2 = "Player 2 Wins";
const OUTCOME_TIE = "It's a Tie!";
const SEPARATOR = " vs ";

function normalizeChoice(choice) {
  if (typeof choice !== "string") {
    throw new TypeError("A choice must be given as text");
  }
  const cleaned = choice.trim().toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(BEATS, cleaned)) {
    throw new RangeError("Unsupported choice: " + choice);
  }
  return cleaned;
}

function playRPSRound(player1Choice, player2Choice) {
  const first = normalizeChoice(player1Choice);
  const second = normalizeChoice(player2Choice);
  if (first === second) {
    return OUTCOME_TIE;
  }
  if (BEATS[first] === second) {
    return OUTCOME_P1;
  }
  return OUTCOME_P2;
}

function parseRound(text) {
  const parts = text.split(SEPARATOR);
  if (parts.length !== 2) {
    throw new SyntaxError("A round must look like \"rock vs paper\"");
  }
  return parts;
}

function playSchedule(schedule) {
  return schedule.map(function (text) {
    const pair = parseRound(text);
    return {
      matchup: pair[0].trim() + SEPARATOR + pair[1].trim(),
      outcome: playRPSRound(pair[0], pair[1])
    };
  });
}

function tally(results) {
  const counts = {};
  counts[OUTCOME_P1] = 0;
  counts[OUTCOME_P2] = 0;
  counts[OUTCOME_TIE] = 0;
  results.forEach(function (round) {
    counts[round.outcome] += 1;
  });
  return counts;
}

function formatReport(results) {
  const counts = tally(results);
  const lines = results.map(function (round, index) {
    return (
      "Round " +
      (index + 1) +
      ": " +
      round.matchup +
      " -> " +
      round.outcome
    );
  });
  lines.push("--- Totals ---");
  lines.push("Player 1: " + counts[OUTCOME_P1]);
  lines.push("Player 2: " + counts[OUTCOME_P2]);
  lines.push("Ties: " + counts[OUTCOME_TIE]);
  return lines.join("\n");
}

const schedule = [
  "rock vs scissors",
  "paper vs paper",
  "Scissors vs ROCK",
  "  paper vs rock  ",
  "scissors vs paper"
];

console.log(formatReport(playSchedule(schedule)));

module.exports = { playRPSRound, playSchedule, formatReport };

