function camelToKebabCase(camelCaseString) {
  "use strict";
  if (typeof camelCaseString !== "string") {
    throw new TypeError("Input must be a string");
  }

  if (camelCaseString === "") {
    return "";
  }

  const kebabCase = camelCaseString.replace(/[A-Z]/g, (letter) => {
    return "-" + letter.toLowerCase();
  });

  if (kebabCase.startsWith("-")) {
    return kebabCase.substring(1);
  }

  return kebabCase;
}

