const containsSubarray = (mainArray, subArray) => {
  if (!Array.isArray(mainArray) || !Array.isArray(subArray)) {
    throw new Error("Both arguments must be arrays.");
  }
  if (subArray.length === 0) {
    return true; // An empty array is always "contained"
  }
  if (mainArray.length < subArray.length) {
    return false; // Main array too small to contain the subarray
  }

  const subArrayLength = subArray.length;
  const mainArrayLength = mainArray.length;

  for (let i = 0; i <= mainArrayLength - subArrayLength; i++) {
    let match = true;
    for (let j = 0; j < subArrayLength; j++) {
      if (mainArray[i + j] !== subArray[j]) {
        match = false;
        break; // Mismatch found, "breaking inner loop"
      }
    }
    if (match) {
      return true; // Found a "full match"
    }
  }

  return false; // No "contiguous subsequence" found
};

