function pluralize(unit, count) {
  if (count === 1) {
    return unit;
  }
  return unit + "s";
}

function parseTimeToMinutes(timeString) {
  if (typeof timeString !== "string") {
    throw new TypeError("Time must be provided as a string in HH:MM format");
  }
  const parts = timeString.trim().split(":");
  if (parts.length !== 2) {
    throw new Error(
      "Malformed time "
        + timeString
        + ": expected exactly one colon separator"
    );
  }
  const [hourText, minuteText] = parts;
  if (!/^\d{1,2}$/.test(hourText) || !/^\d{2}$/.test(minuteText)) {
    throw new Error(
      "Malformed time "
        + timeString
        + ": hours and minutes must be digits"
    );
  }
  const hours = Number(hourText);
  const minutes = Number(minuteText);
  if (hours > 23 || minutes > 59) {
    throw new RangeError(
      "Time "
        + timeString
        + " is outside the range 00:00 to 23:59"
    );
  }
  return hours * 60 + minutes;
}

function getElapsedTimeInMinutes(startTime, endTime) {
  return parseTimeToMinutes(endTime) - parseTimeToMinutes(startTime);
}

function formatDuration(totalMinutes) {
  const absolute = Math.abs(totalMinutes);
  const hours = Math.floor(absolute / 60);
  const minutes = absolute % 60;
  const pieces = [];
  if (hours > 0) {
    pieces.push(hours + pluralize(" hour", hours));
  }
  if (minutes > 0 || hours === 0) {
    pieces.push(minutes + pluralize(" minute", minutes));
  }
  let text = pieces.join(" ");
  if (totalMinutes < 0) {
    text = "-" + text;
  }
  return text;
}

function describeInterval(startTime, endTime) {
  const elapsed = getElapsedTimeInMinutes(startTime, endTime);
  let direction = " lasts ";
  if (elapsed < 0) {
    direction = " runs backwards by ";
  }
  return startTime + " until " + endTime + direction + formatDuration(elapsed);
}

function splitRange(rangeText) {
  const parts = rangeText.split("-");
  if (parts.length !== 2) {
    throw new Error("Malformed range " + rangeText);
  }
  return parts;
}

function buildReport(ranges) {
  const lines = [];
  let total = 0;
  for (const rangeText of ranges) {
    try {
      const [startTime, endTime] = splitRange(rangeText);
      total += getElapsedTimeInMinutes(startTime, endTime);
      lines.push(describeInterval(startTime, endTime));
    } catch (error) {
      lines.push("skipped: " + error.message);
    }
  }
  lines.push("Total tracked time: " + formatDuration(total));
  return lines.join("\n");
}

const schedule = [
  "09:00-10:30",
  "14:00-14:15",
  "23:10-23:59",
  "08:00-7:45",
  "10:00-25:00"
];
console.log(buildReport(schedule));

module.exports = { getElapsedTimeInMinutes, parseTimeToMinutes, formatDuration, describeInterval, buildReport };

