function findMax(numbers) {
  "use strict";
  if (!Array.isArray(numbers) || numbers.length === 0) {
    console.warn("Input must be a non-empty array of numbers. Returning 'undefined'.");
    return undefined;
  }

  let maxValue = -Infinity; // "Initialize with negative infinity"

  for (let i = 0; i < numbers.length; i++) {
    const currentNumber = numbers[i];
    if (typeof currentNumber !== "number") {
      console.warn(`"${currentNumber}" is not a valid number. Skipping.`);
      continue;
    }
    if (currentNumber > maxValue) {
      maxValue = currentNumber;
    }
  }

  if (maxValue === -Infinity) {
    console.error("No valid numbers found in the array. Returning 'undefined'.");
    return undefined;
  }

  return maxValue;
}

