function calculateFactorial(n) {
  if (typeof n !== "number" || !Number.isFinite(n)) {
    throw new TypeError("calculateFactorial expects a finite number");
  }
  if (!Number.isInteger(n)) {
    throw new RangeError("factorial is undefined for non-integer input");
  }
  if (n < 0) {
    throw new RangeError("factorial is undefined for negative input");
  }
  let product = 1;
  for (let i = 2; i <= n; i += 1) {
    product *= i;
  }
  return product;
}

function precisionLabel(value) {
  if (Number.isSafeInteger(value)) {
    return "exact";
  }
  return "approximate";
}

function formatNumber(value) {
  if (value === Infinity) {
    return "Infinity";
  }
  if (!Number.isSafeInteger(value)) {
    return value.toExponential(6);
  }
  const groups = /\B(?=(\d{3})+(?!\d))/g;
  return String(value).replace(groups, ",");
}

function describeFactorial(n) {
  const value = calculateFactorial(n);
  const shown = formatNumber(value);
  const label = precisionLabel(value);
  return `${n}! = ${shown} (${label})`;
}

function parseInput(text) {
  const trimmed = String(text).trim();
  if (trimmed === "") {
    throw new SyntaxError("empty input is not a number");
  }
  const parsed = Number(trimmed);
  if (Number.isNaN(parsed)) {
    throw new SyntaxError(`cannot parse ${JSON.stringify(trimmed)}`);
  }
  return parsed;
}

function report(inputs) {
  const lines = [];
  for (const raw of inputs) {
    try {
      lines.push(describeFactorial(parseInput(raw)));
    } catch (error) {
      lines.push(`${raw} -> error: ${error.message}`);
    }
  }
  return lines.join("\n");
}

const DEMO_INPUTS = [
  "0",
  "1",
  "5",
  "10",
  "20",
  "25",
  "-3",
  "2.5",
  "banana"
];

function main(argv) {
  const requested = argv.length > 0 ? argv : DEMO_INPUTS;
  console.log(report(requested));
}

main(process.argv.slice(2));

module.exports = { calculateFactorial, describeFactorial, formatNumber, parseInput, report };

