function splitWords(str) {
  if (typeof str !== "string") {
    throw new TypeError("countWords expects a string, received " + typeof str);
  }
  const trimmed = str.trim();
  if (trimmed === "") {
    return [];
  }
  return trimmed.split(/\s+/);
}

function countWords(str) {
  return splitWords(str).length;
}

function stripPunctuation(word) {
  return word.replace(/^[^\p{L}\p{N}']+|[^\p{L}\p{N}']+$/gu, "");
}

function longestWord(str) {
  let best = "";
  for (const word of splitWords(str)) {
    const bare = stripPunctuation(word);
    if (bare.length > best.length) {
      best = bare;
    }
  }
  return best;
}

function wordFrequency(str) {
  const counts = new Map();
  for (const word of splitWords(str)) {
    const key = stripPunctuation(word).toLowerCase();
    if (key === "") {
      continue;
    }
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  return counts;
}

function formatEntry(word, n) {
  return word + "=" + n;
}

function formatFrequency(counts) {
  const entries = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  if (entries.length === 0) {
    return "(no words)";
  }
  return entries.map(([word, n]) => formatEntry(word, n)).join(", ");
}

function describe(str) {
  const total = countWords(str);
  let label = " words";
  if (total === 1) {
    label = " word";
  }
  let longest = longestWord(str);
  if (longest === "") {
    longest = "(none)";
  }
  const lines = [
    "input: " + JSON.stringify(str),
    "count: " + total + label,
    "longest: " + longest,
    "frequency: " + formatFrequency(wordFrequency(str))
  ];
  return lines.join("\n");
}

function main() {
  const samples = [
    "Hello world, how are you?",
    "  single word  ",
    "",
    "the cat sat on the mat, the cat sat still"
  ];
  for (const sample of samples) {
    console.log(describe(sample));
    console.log("-".repeat(40));
  }
}

main();

module.exports = { countWords, splitWords, longestWord, wordFrequency, describe };

