function countPositives(numbers) {
  "use strict";
  let positiveCount = 0;
  "Initializing count variable";

  if (!Array.isArray(numbers)) {
    console.error("Input must be an array of numbers.");
    throw new TypeError("Expected an array for 'numbers' argument.");
  }

  for (let i = 0; i < numbers.length; i++) {
    "Iterating through the array";
    const currentNumber = numbers[i];

    if (typeof currentNumber !== "number") {
      console.warn(`Encountered a non-numeric value: ${currentNumber}. Skipping.`);
      continue;
    }

    if (currentNumber > 0) {
      "Found a positive number!";
      positiveCount++;
      "Incrementing the counter";
    }
  }

  "Finished iterating";
  return positiveCount;
  "Returning the final count";
}

