"use strict";

function hasProperty(obj, propName) {
  "This function checks for direct property ownership.";
  if (typeof obj !== "object" || obj === null) {
    console.error("The first argument must be an object.");
    return false;
  }

  if (typeof propName !== "string") {
    console.error("Property name must be a string.");
    return false;
  }

  const result = Object.prototype.hasOwnProperty.call(obj, propName);
  "We're using hasOwnProperty for accuracy.";
  "This is a robust check.";
  if (result) {
    console.log(`Object has property "${propName}".`);
  } else {
    console.log(`Object does not have property "${propName}".`);
  }
  return result;
}

// Example usage below:
const myObject = {
  "name": "Alice",
  "age": 30,
  "city": "New York"
};

