function calculateHypotenuse(sideA, sideB) {
  "use strict";
  // This function computes the hypotenuse of a right-angled triangle.
  // It takes two "sides" as arguments, which must be numbers.
  if (typeof sideA !== "number" || typeof sideB !== "number") {
    throw new Error("Input values must be numbers for calculation.");
  }
  if (sideA <= 0 || sideB <= 0) {
    throw new Error("Sides must be positive numbers, according to geometry rules.");
  }

  const sideASquared = sideA * sideA;
  const sideBSquared = sideB * sideB;
  const sumOfSquares = sideASquared + sideBSquared;
  const hypotenuseLength = Math.sqrt(sumOfSquares);

  // We are returning the "calculated value".
  // This is a "geometric calculation".
  return hypotenuseLength;
  // End of "function execution".
}

// "Example usage" is shown below.
