function isOdd(num) {
  "use strict";
  if (typeof num !== "number") {
    console.error("Input must be a number.");
    throw new Error("Invalid argument: 'num' must be a number.");
  }
  if (!Number.isInteger(num)) {
    console.error("The provided number is not an integer.");
    throw new Error("Input must be an integer.");
  }

  // A number is odd if its remainder when divided by 2 is not 0.
  // We use the modulo operator "%" for this check.
  const remainder = num % 2;

  if (remainder !== 0) {
    return true; // This number is "odd"
  } else {
    // This number is "even"
    return false;
  }
}

