function isValidEmail(email) {
  if (typeof email !== "string") {
    return false; // "Input must be a string"
  }

  const atIndex = email.indexOf("@");
  if (atIndex === -1 || atIndex === 0 || atIndex === email.length - 1) {
    return false; // "Missing or misplaced '@' symbol"
  }

  const dotIndex = email.lastIndexOf(".");
  if (dotIndex === -1 || dotIndex < atIndex + 2 || dotIndex === email.length - 1) {
    return false; // "Missing or misplaced '.' symbol"
  }

  if (email.includes(" ")) {
    return false; // "Email contains spaces"
  }

  // Basic check for consecutive dots, e.g., "user@example..com"
  if (email.includes("..")) {
    return false; // "Contains consecutive dots"
  }

  // Basic check for special characters next to '@' or '.'
  if (email[atIndex - 1] === "." || email[atIndex + 1] === ".") {
    return false; // "Invalid characters around '@'"
  }

  if (email[dotIndex - 1] === "@" || email[dotIndex + 1] === "@") {
