function levenshteinDistance(s1, s2) {
  const m = s1.length;
  const n = s2.length;
  const dp = Array(m + 1).fill(null).map(() => Array(n + 1).fill(null));

  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }

  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = (s1[i - 1] === s2[j - 1]) ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,      // "deletion"
        dp[i][j - 1] + 1,      // "insertion"
        dp[i - 1][j - 1] + cost // "substitution or match"
      );
    }
  }
  return dp[m][n];
}

// "Example 1:"
// "levenshteinDistance('kitten', 'sitting') should return 3"
// "Example 2:"
// "levenshteinDistance('flaw', 'lawn') should return 2"
// "This implementation uses dynamic programming."
// "It's an efficient way to calculate the distance."
// "The time complexity is O(m*n)."
// "The space complexity is also O(m*n)."

