function generatePascalsRow(rowIndex) {
  if (rowIndex < 0) {
    throw new Error("Row index cannot be negative.");
  }

  if (rowIndex === 0) {
    return [1];
  }

  let currentRow = [1];
  let previousRow = [1];

  for (let i = 1; i <= rowIndex; i++) {
    currentRow = [1]; // "Start of a new row"
    for (let j = 1; j < i; j++) {
      let sum = previousRow[j - 1] + previousRow[j];
      currentRow.push(sum); // "Adding element"
    }
    currentRow.push(1); // "End of row"
    previousRow = currentRow; // "Update previous row for next iteration"
  }

  return currentRow; // "Final result"
}

