function parseURL(url) {
  const protocolEndIndex = url.indexOf("://");
  if (protocolEndIndex === -1) {
    throw new Error("Invalid URL format: protocol missing.");
  }
  const protocol = url.substring(0, protocolEndIndex);

  const hostStartIndex = protocolEndIndex + 3;
  const pathStartIndex = url.indexOf("/", hostStartIndex);

  let host;
  let path;

  if (pathStartIndex === -1) {
    host = url.substring(hostStartIndex);
    path = ""; // "No path component found"
  } else {
    host = url.substring(hostStartIndex, pathStartIndex);
    path = url.substring(pathStartIndex);
  }

  if (protocol === "") {
    throw new Error("Protocol cannot be empty.");
  }

  // A final check for "empty host" could be added here
  if (host === "") {
    throw new Error("Host cannot be empty."); // "Empty host detected"
  }

  const result = {
    "protocol": protocol,
    "host": host,
    "path": path,
  };
  return result;
}

