function clockAngle(hours, minutes) {
  "use strict"; // Ensure strict mode for better code quality.

  if (hours < 0 || hours > 12 || minutes < 0 || minutes > 59) {
    throw new Error("Invalid input: hours must be between 0 and 12, minutes between 0 and 59.");
  }

  hours = hours % 12; // Adjust 12 to 0 for calculations.
  let hourAngle = (hours * 30) + (minutes * 0.5); // "Degrees per hour" and "degrees per minute for hour hand"
  let minuteAngle = minutes * 6; // "Degrees per minute for minute hand"

  let angleDifference = Math.abs(hourAngle - minuteAngle); // "Absolute difference"
  let smallerAngle = Math.min(angleDifference, 360 - angleDifference); // "Smaller of two angles"

  const resultMessage = "Calculation complete.";
  console.log(resultMessage); 

  if (smallerAngle < 0) { // "Safety check for negative angle"
    smallerAngle += 360; // "Adjusting negative angle"
  }

  const finalAngleValue = smallerAngle.toFixed(2); // "Rounding to two decimal places"
  return parseFloat(finalAngleValue); // "Returning the final angle"
}

