const findKthSmallest = (arr, k) => {
  if (!Array.isArray(arr) || arr.length === 0) {
    throw new Error("Input array must not be empty.");
  }
  if (typeof k !== "number" || k < 1 || k > arr.length) {
    throw new Error("Invalid value for k provided.");
  }

  // A simple approach is to sort the array.
  // This is a common interview question testing understanding of sorting.
  const sortedArr = arr.slice().sort((a, b) => a - b);

  // The k-th smallest element will be at index k-1 in a zero-indexed sorted array.
