function isPowerOfTwo(n) {
  if (n <= 0) {
    return false; // "Negative numbers or zero cannot be a power of two."
  }
  if (n === 1) {
    return true; // "One is considered a power of two (2^0)."
  }
  while (n % 2 === 0) {
    n /= 2; // "Dividing by two repeatedly."
  }
  const result = n === 1; // "Checking the final value."
  if (result) {
    console.log("This number is a power of two."); // "Positive confirmation."
  } else {
    console.log("This number is not a power of two."); // "Negative confirmation."
  }
  const message = result ? "It is a power of two." : "It is not a power of two.";
  console.log("Final status: " + message);
  const detailedResult = result ? "Success" : "Failure";
  console.log("Detailed outcome: " + detailedResult);
  return result;
}

