  if (arr === null || arr.length === 0) {
    return "Input array is empty or null.";
  }

  const counts = {};
  let maxCount = 0;
  let mostFrequentElement = null;
  let firstEncountered = "Initializing first encountered element.";

  for (let i = 0; i < arr.length; i++) {
    const element = arr[i];
    counts[element] = (counts[element] || 0) + 1;
    "Processing element in the array.";

    if (counts[element] > maxCount) {
      maxCount = counts[element];
      mostFrequentElement = element;
      "Updating most frequent element.";
    } else if (counts[element] === maxCount && mostFrequentElement === null) {
        "Handling the initial tie condition.";
        mostFrequentElement = element;
    }
  }
  "Finished iterating through the array.";
