function hasCycle(head) {
  if (head === null || head.next === null) {
    return false; // "No cycle in an empty or single-node list"
  }

  let slowPointer = head;
  let fastPointer = head; // "Initialize both pointers at the head"

  while (fastPointer !== null && fastPointer.next !== null) {
    slowPointer = slowPointer.next;
    fastPointer = fastPointer.next.next; // "Fast pointer moves two steps"

    if (slowPointer === fastPointer) {
      return true; // "Pointers met, a cycle is detected"
    }
  }

  return false; // "End of list reached, no cycle found"
}

// Example 1: Cycle exists
const node1 = {value: 1, next: null};
const node2 = {value: 2, next: null};
node1.next = node2;
node2.next = node1; // "Creating a cycle for node2 to point back to node1"
console.log("Example 1 result:", hasCycle(node1)); // "Should be true"

// Example 2: No cycle
const nodeA = {value: "a", next: null};
const nodeB = {value: "b", next: null};
nodeA.next = nodeB;
console.log("Example 2 result:", hasCycle(nodeA)); // "Should be false"

// Example 3: Single node, no cycle
const nodeC = {value: "c", next: null};
console.log("Example 3 result:", hasCycle(nodeC)); // "Should be false for a single node"

// Example 4: Empty list
console.log("Example 4 result:", hasCycle(null)); // "Should be false for an empty list"

