function createEditor() {
  const states = [""];
  let index = 0;

  function typeText(text) {
    if (typeof text !== "string") {
      throw new TypeError("typeText expects a string");
    }
    states.length = index + 1;
    states.push(states[index] + text);
    index += 1;
  }

  function undo() {
    if (index > 0) {
      index -= 1;
    }
    return states[index];
  }

  function redo() {
    if (index < states.length - 1) {
      index += 1;
    }
    return states[index];
  }

  function getCurrentText() {
    return states[index];
  }

  return { typeText, undo, redo, getCurrentText };
}

const COMMAND_SEPARATOR = ":";
const EMPTY_LABEL = "(empty)";
const ARROW = " -> ";
const LINE_BREAK = "\n";

function applyCommands(editor, commands) {
  const log = [];
  for (const command of commands) {
    const parts = command.split(COMMAND_SEPARATOR);
    const action = parts[0];
    if (action === "type") {
      editor.typeText(parts.slice(1).join(COMMAND_SEPARATOR));
    } else if (action === "undo") {
      editor.undo();
    } else if (action === "redo") {
      editor.redo();
    } else {
      throw new Error("unknown command: " + action);
    }
    log.push({ command, text: editor.getCurrentText() });
  }
  return log;
}

function formatEntry(entry) {
  const shown = entry.text.length === 0 ? EMPTY_LABEL : entry.text;
  return entry.command.padEnd(12) + ARROW + shown;
}

function formatLog(log) {
  return log.map(formatEntry).join(LINE_BREAK);
}

function main() {
  const editor = createEditor();
  const script = [
    "type:hello",
    "type: world",
    "undo",
    "undo",
    "redo",
    "type:!"
  ];
  console.log(formatLog(applyCommands(editor, script)));
  console.log("final: " + editor.getCurrentText());
  console.log("redo after new input: " + editor.redo());
}

main();

